<?php declare(strict_types=1); $base=config('app.base_path'); $isTrash=!empty($trash); ?><div class="page-header"><div><h1><?= $isTrash?'Deleted Menu Categories':'Menu Categories' ?></h1><p><?= $isTrash?'Restore categories from Trash.':'Organize restaurant menus into customer-friendly sections.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/categories">Active Categories</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/categories?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/restaurant/categories/create">Add Category</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Restaurant</th><th>Category</th><th>Items</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($categories)): ?><tr><td colspan="6"><div class="empty-state"><?= $isTrash?'Trash is empty.':'No categories found.' ?></div></td></tr><?php else: foreach($categories as $c): ?><tr><td><?= htmlspecialchars((string)$c['restaurant_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)$c['name'],ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$c['item_count'] ?></td><td><?= (int)$c['sort_order'] ?></td><td><?= htmlspecialchars((string)$c['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($isTrash): ?><form method="post" action="<?= $base ?>/restaurant/categories/<?= (int)$c['id'] ?>/restore"><button class="btn btn-secondary" type="submit">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/restaurant/categories/<?= (int)$c['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif; ?></tbody></table></div>
